import{_ as r,a0 as i,w as p,s,ao as d,I as a,x as t,a1 as o,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode","title":"如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器","tag":"201810","desc":""},"relativePath":"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode.md","filePath":"[post].md"}'),l={name:"201810/20180925 How to Boot Ubuntu 18.04 - Debian 9 Server in Rescue (Single User mode) - Emergency Mode.md"};function c(b,e,m,g,h,w){const n=i("Link");return p(),s("div",null,[e[15]||(e[15]=d('<h1 id="如何在救援-单用户模式-紧急模式下启动-ubuntu-18-04-debian-9-服务器" tabindex="-1">如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器 <a class="header-anchor" href="#如何在救援-单用户模式-紧急模式下启动-ubuntu-18-04-debian-9-服务器" aria-label="Permalink to “如何在救援（单用户模式）/紧急模式下启动 Ubuntu 18.04/Debian 9 服务器”">​</a></h1><p>将 Linux 服务器引导到单用户模式或<ruby>救援模式<rt>rescue mode</rt></ruby>是 Linux 管理员在关键时刻恢复服务器时通常使用的重要故障排除方法之一。在 Ubuntu 18.04 和 Debian 9 中，单用户模式被称为救援模式。</p><p>除了救援模式外，Linux 服务器可以在<ruby>紧急模式<rt>emergency mode</rt></ruby>下启动，它们之间的主要区别在于，紧急模式加载了带有只读根文件系统文件系统的最小环境，没有启用任何网络或其他服务。但救援模式尝试挂载所有本地文件系统并尝试启动一些重要的服务，包括网络。</p><p>在本文中，我们将讨论如何在救援模式和紧急模式下启动 Ubuntu 18.04 LTS/Debian 9 服务器。</p><h4 id="在单用户-救援模式下启动-ubuntu-18-04-lts-服务器" tabindex="-1">在单用户/救援模式下启动 Ubuntu 18.04 LTS 服务器： <a class="header-anchor" href="#在单用户-救援模式下启动-ubuntu-18-04-lts-服务器" aria-label="Permalink to “在单用户/救援模式下启动 Ubuntu 18.04 LTS 服务器：”">​</a></h4><p>重启服务器并进入启动加载程序 （Grub） 屏幕并选择 “Ubuntu”，启动加载器页面如下所示，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Bootloader-Screen-Ubuntu18-04-Server.jpg" alt=""></p><p>按下 <code>e</code>，然后移动到以 <code>linux</code> 开头的行尾，并添加 <code>systemd.unit=rescue.target</code>。如果存在单词 <code>$vt_handoff</code> 就删除它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/rescue-target-ubuntu18-04.jpg" alt=""></p><p>现在按 <code>Ctrl-x</code> 或 <code>F10</code> 启动，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/rescue-mode-ubuntu18-04.jpg" alt=""></p><p>现在按回车键，然后你将得到所有文件系统都以读写模式挂载的 shell 并进行故障排除。完成故障排除后，可以使用 <code>reboot</code> 命令重新启动服务器。</p><h4 id="在紧急模式下启动-ubuntu-18-04-lts-服务器" tabindex="-1">在紧急模式下启动 Ubuntu 18.04 LTS 服务器 <a class="header-anchor" href="#在紧急模式下启动-ubuntu-18-04-lts-服务器" aria-label="Permalink to “在紧急模式下启动 Ubuntu 18.04 LTS 服务器”">​</a></h4><p>重启服务器并进入启动加载程序页面并选择 “Ubuntu”，然后按 <code>e</code> 并移动到以 <code>linux</code> 开头的行尾，并添加 <code>systemd.unit=emergency.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergecny-target-ubuntu18-04-server.jpg" alt=""></p><p>现在按 <code>Ctrl-x</code> 或 <code>F10</code> 以紧急模式启动，你将获得一个 shell 并从那里进行故障排除。正如我们已经讨论过的那样，在紧急模式下，文件系统将以只读模式挂载，并且在这种模式下也不会有网络，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-prompt-debian9.jpg" alt=""></p><p>使用以下命令将根文件系统挂载到读写模式，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,rw /</span></span></code></pre></div><p>同样，你可以在读写模式下重新挂载其余文件系统。</p><h4 id="将-debian-9-引导到救援和紧急模式" tabindex="-1">将 Debian 9 引导到救援和紧急模式 <a class="header-anchor" href="#将-debian-9-引导到救援和紧急模式" aria-label="Permalink to “将 Debian 9 引导到救援和紧急模式”">​</a></h4><p>重启 Debian 9.x 服务器并进入 grub页面选择 “Debian GNU/Linux”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Debian9-Grub-Screen.jpg" alt=""></p><p>按下 <code>e</code> 并移动到 linux 开头的行尾并添加 <code>systemd.unit=rescue.target</code> 以在救援模式下启动系统， 要在紧急模式下启动，那就添加 <code>systemd.unit=emergency.target</code>。</p><h4 id="救援模式" tabindex="-1">救援模式： <a class="header-anchor" href="#救援模式" aria-label="Permalink to “救援模式：”">​</a></h4><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Rescue-mode-Debian9.jpg" alt=""></p><p>现在按 <code>Ctrl-x</code> 或 <code>F10</code> 以救援模式启动</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Rescue-Mode-Shell-Debian9.jpg" alt=""></p><p>按下回车键以获取 shell，然后从这里开始故障排除。</p><h4 id="紧急模式" tabindex="-1">紧急模式： <a class="header-anchor" href="#紧急模式" aria-label="Permalink to “紧急模式：”">​</a></h4><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-target-grub-debian9.jpg" alt=""></p><p>现在按下 <code>ctrl-x</code> 或 <code>F10</code> 以紧急模式启动系统</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/09/Emergency-prompt-debian9.jpg" alt=""></p><p>按下回车获取 shell 并使用 <code>mount -o remount,rw /</code> 命令以读写模式挂载根文件系统。</p><p><strong>注意：</strong>如果已经在 Ubuntu 18.04 和 Debian 9 Server 中设置了 root 密码，那么你必须输入 root 密码才能在救援和紧急模式下获得 shell</p><p>就是这些了，如果您喜欢这篇文章，请分享你的反馈和评论。</p><hr>',37)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),o(n,{href:"https://www.linuxtechi.com/boot-ubuntu-18-04-debian-9-rescue-emergency-mode/"},{default:u(()=>[...e[0]||(e[0]=[t("https://www.linuxtechi.com/boot-ubuntu-18-04-debian-9-rescue-emergency-mode/",-1)])]),_:1})]),a("p",null,[e[6]||(e[6]=t("作者：",-1)),o(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:u(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:u(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:u(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:u(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:u(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const D=r(l,[["render",c]]);export{T as __pageData,D as default};
